do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'd3c7cdd2-7722-5cf6-e076-781be7317238',
  'bank-of-thailand-museum',
  'พิพิธภัณฑ์ธนาคารแห่งประเทศไทย',
  'Bank of Thailand Museum',
  'พิพิธภัณฑ์ธนาคารแห่งประเทศไทย เป็นพิพิธภัณฑ์ในกรุงเทพมหานคร ตั้งอยู่ในวังบางขุนพรหมซึ่งเป็นที่ประทับเดิมของสมเด็จพระเจ้าบรมวงศ์เธอ เจ้าฟ้าบริพัตรสุขุมพันธุ์ กรมพระนครสวรรค์วรพินิต เป็นพระราชโอรสคนที่ 33 ในพระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว พระมหากษัตริย์รัชกาลที่ 5 แห่งกรุงรัตนโกสินทร์ นอกจากนี้พิพิธภัณฑ์ยังมีสาขาย่อยที่จังหวัดเชียงใหม่ด้วย พิพิธภัณฑ์ธนาคารแห่งประเทศไทย จัดแสดงสื่อในการแลกเปลี่ยนเมื่อยุคก่อนประวัติศาสตร์ โดยแบ่งออกเป็นห้องต่าง ๆ เช่น ห้องเงินตราโบราณ ห้องกษาปณ์ไทย ห้องเงินพดด้วง ห้องธนบัตรไทย ห้องทองตรา ห้อง 50 ปี ตัวพิพิธภัณฑ์มีพื้นที่ทั้งหมด 30 ไร่ อาคารเคยถูกใช้เป็นสถานที่ราชการอยู่ระยะหนึ่ง กระทั่งปี พ.ศ. 2525 เปลี่ยนมาเป็นพิพิธภัณฑ์ธนาคารแห่งประเทศไทย',
  'Bank of Thailand Museum is a museum in Bangkok. The museum is housed in the Bang Khun Phrom Palace, the former residence of Prince Paribatra Sukhumbandhu, who was the 33rd son of King Chulalongkorn. The Bank of Thailand, Northern Region also has a museum in Chiang Mai. In June 2017, the museum was reopened.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%9E%E0%B8%B4%E0%B8%9E%E0%B8%B4%E0%B8%98%E0%B8%A0%E0%B8%B1%E0%B8%93%E0%B8%91%E0%B9%8C%E0%B8%98%E0%B8%99%E0%B8%B2%E0%B8%84%E0%B8%B2%E0%B8%A3%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B9%80%E0%B8%97%E0%B8%A8%E0%B9%84%E0%B8%97%E0%B8%A2","license":"CC BY-SA 4.0"}'::jsonb,
