insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'9e7655ce-2958-55ef-d9e5-75632a5a7b14',
  'chatuchak-weekend-market',
  'ตลาดนัดจตุจักร',
  'Chatuchak Weekend Market',
  'ตลาดนัดจตุจักร เป็นตลาดนัดในกรุงเทพมหานครที่ได้รับความนิยมจากคนไทยและชาวต่างชาติ มีจำนวนแผงค้าทั้งหมดมากกว่า 8,000 แผงค้า แบ่งเป็น 27 โครงการ มีสินค้า 8 ประเภท ได้แก่ ผักและผลไม้ เสื้อผ้า สัตว์เลี้ยง ต้นไม้ อาหารปรุง อาหารสำเร็จรูป อาหารสด และเบ็ดเตล็ด ตลาดนัดจตุจักรถูกสร้างขึ้นโดย พลเอก เกรียงศักดิ์ ชมะนันท์ ในสมัยปี พ.ศ. 2521 เป็นที่ดินของการรถไฟแห่งประเทศไทยซึ่งในขณะนั้น พลเอกเกรียงศักดิ์ ชมะนันท์ เป็นประธานกรรมการรถไฟ โดยการเอากองขยะที่ดินแดง มาถม ที่ของการรถไฟแห่งประเทศไทย แล้วย้ายตลาดนัดสนามหลวงมาที่นี่ โดยใช้ทหารช่างมาทำการสร้างขึ้น',
  'The Chatuchak Weekend Market (Thai: ตลาดนัดจตุจักร, RTGS: Talatnat Chatuchak ), on Kamphaeng Phet 2 Road, Chatuchak, Bangkok, is the largest market in Thailand. Afectionately known as JJ Market, it has more than 15,000 stalls and 11,505 vendors (2019), divided into 27 sections. Chatuchak Market sells many different kinds of goods, including plants, antiques, consumer electronics, cosmetics, pets, fresh and dry food and drinks, ceramics, furniture and home accessories, clothing, and books. It is the world''s largest and most diverse weekend market, with over 200,000 visitors every weekend.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%95%E0%B8%A5%E0%B8%B2%E0%B8%94%E0%B8%99%E0%B8%B1%E0%B8%94%E0%B8%88%E0%B8%95%E0%B8%B8%E0%B8%88%E0%B8%B1%E0%B8%81%E0%B8%A3","license":"CC BY-SA 4.0"}'::jsonb,
