do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'74f7c173-2763-5749-2107-59d9ba343a48',
  'doi-suthep-pui-national-park',
  'อุทยานแห่งชาติดอยสุเทพ-ปุย',
  'Doi Suthep-Pui National Park',
  'อุทยานแห่งชาติดอยสุเทพ-ปุย เป็นอุทยานแห่งชาติที่ตั้งอยู่ในเขตอำเภอเมืองเชียงใหม่ อำเภอแม่ริม และอำเภอหางดง ของจังหวัดเชียงใหม่ มีพื้นที่ทั้งหมด 163,162.5 ไร่ หรือประมาณ 261 ตารางกิโลเมตร จุดสูงสุดของอุทยานแห่งชาติอยู่บริเวณที่เรียกว่า ดอยปุย ซึ่งสูงกว่าระดับน้ำทะเล 1,685 เมตร อุทยานแห่งชาติแห่งนี้ประกอบด้วยป่าที่อุดมสมบูรณ์ แม้ว่าจะตั้งอยู่ใกล้ตัวเมืองเชียงใหม่มาก แต่ป่าส่วนใหญ่อยู่บนภูเขาสูงสลับซับซ้อน ภูเขาสำคัญ ได้แก่ ดอยสุเทพ ดอยปุย เป็นต้น นอกจากนี้ อุทยานแห่งชาติดอยสุเทพ-ปุย ยังเป็นที่ตั้งของสถานที่สำคัญ 2 แห่งได้แก่ วัดพระธาตุดอยสุเทพราชวรวิหาร และพระตำหนักภูพิงคราชนิเวศน์',
  'Doi Suthep–Pui National Park (Thai: อุทยานแห่งชาติดอยสุเทพ-ปุย) is a national park in Chiang Mai Province in Thailand. It includes Wat Phra That Doi Suthep, a Buddhist temple, and Bhubing Palace, the winter residence of the Thai royal family. The park is a protected area for flora, fauna, and habitat.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%AD%E0%B8%B8%E0%B8%97%E0%B8%A2%E0%B8%B2%E0%B8%99%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B8%94%E0%B8%AD%E0%B8%A2%E0%B8%AA%E0%B8%B8%E0%B9%80%E0%B8%97%E0%B8%9E-%E0%B8%9B%E0%B8%B8%E0%B8%A2","license":"CC BY-SA 4.0"}'::jsonb,
