do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'e9a721e7-7c04-5a6f-8eef-e983a099f762',
  'kaeng-tana-national-park',
  'อุทยานแห่งชาติแก่งตะนะ',
  'Kaeng Tana National Park',
  'อุทยานแห่งชาติแก่งตะนะ ตั้งอยู่ในท้องที่ อำเภอโขงเจียม และอำเภอสิรินธร จังหวัดอุบลราชธานี สภาพ พื้นที่ทั่วไปเป็นที่ราบและเนินเขาเตี้ยๆ โดยมียอดเขาบรรทัดเป็นจุดสูงสุด ความสูงประมาณ 543 เมตรจากระดับน้ำทะเลปานกลาง มีแม่น้ำมูลและแม่น้ำโขงไหลผ่านตามแนวเขตทางด้านทิศเหนือไปออกประเทศลาว บริเวณแก่งตะนะจะมีสายน้ำที่เชี่ยวและลึก อีกทั้งยังมีถ้ำใต้น้ำหลายแห่ง จึงทำให้มีปลาอาศัยอยู่ชุกชุม ตรงกลางมีโขดหินขนาดใหญ่เป็นเกาะกลาง มีเนื้อที่ประมาณ 50,000 ไร่ หรือ 80 ตารางกิโลเมตร คำว่า “ตะนะ” จากการเล่าขานตามความเชื่อของชาวบ้านและประชาชนทั่วไป เดิมมาจากคำว่า “มรณะ” เนื่องจากบริเวณแก่งตะนะนี้มีกระแสน้ำไหลที่เชี่ยวกราก และมีโขดหินใหญ่น้อยอยู่ทั่วไป ตลอดจนมีถ้ำใต้น้ำอยู่หลายแห่ง ชาวบ้านที่สัญจรทางน้ำหรือออกจับปลา มักประสบอุบัติเหตุเสียชีวิตอยู่เป็นประจำ ชาวบ้านจึงเรียกแก่งนี้ว่า “แก่งมรณะ” ตามแรงบันดาลจากสภาพของสายน้ำที่ไหลผ่านแก่งนี้ ซึ่งต่อมาเรียกว่า “แก่งตะนะ” จึงตั้งเป็นชื่ออุทยานแห่งชาติ',
  'Kaeng Tana National Park is in Khong Chiam District in Ubon Ratchathani Province, northeastern Thailand. It is on the Mun River. It was established on 13 July 1981 and is an IUCN Category II protected area.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%AD%E0%B8%B8%E0%B8%97%E0%B8%A2%E0%B8%B2%E0%B8%99%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B9%81%E0%B8%81%E0%B9%88%E0%B8%87%E0%B8%95%E0%B8%B0%E0%B8%99%E0%B8%B0","license":"CC BY-SA 4.0"}'::jsonb,
  'ubon-ratchathani',
  'Ubon Ratchathani',
  'อุบลราชธานี',
  'Northeast',
  'C',
  null,
  null,
  15.29722222,
  105.47361111,
  '{"name":"Wikidata","url":"https://www.wikidata.org/wiki/Q6652894","property":"P625","confidence":100}'::jsonb,
  'national park',
  'unknown',
  'unknown',
  'unknown',
  null,
