do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'996b04f5-bd68-50ef-f9dd-cbf4e18ec5e2',
  'khlong-bangkok-noi',
  'คลองบางกอกน้อย',
  'Khlong Bangkok Noi',
  'คลองบางกอกน้อย ตั้งอยู่ในกรุงเทพมหานครและจังหวัดนนทบุรี เดิมเคยเป็นส่วนหนึ่งของแม่น้ำเจ้าพระยา จนกระทั่งรัชสมัยสมเด็จพระไชยราชาธิราชแห่งกรุงศรีอยุธยา (พ.ศ. 2077–2089) ได้โปรดเกล้าฯ ให้ขุดคลองลัดแม่น้ำขึ้นจากปากคลองบางกอกน้อยไปยังปากคลองบางกอกใหญ่ ซึ่งกล่าวกันว่าช่วยย่นระยะทางได้ถึง 1 วัน ต่อมากระแสน้ำส่วนใหญ่ได้ไหลเข้าสู่คลองลัดทำให้คลองกว้างขึ้นเรื่อย ๆ กลายเป็นแม่น้ำเจ้าพระยาสายใหม่ ส่วนแม่น้ำสายเดิมแคบลงกลายเป็นคลองบางกอกน้อย คลองชักพระ และคลองบางกอกใหญ่แทน คลองบางกอกน้อยเริ่มต้นตั้งแต่แม่น้ำเจ้าพระยาทางเหนือของสถานีรถไฟธนบุรี ไหลขึ้นไปบรรจบคลองชักพระ (คลองบางขุนศรี) และคลองลัดบางกรวย ตรงข้ามวัดสุวรรณคีรี มีความกว้างมากถึง 40 เมตร และยาว 3.3 กิโลเมตร คณะรัฐมนตรีมีมติให้คลองบางกอกน้อยเป็นคลองสำคัญซึ่งจะต้องอนุรักษ์ไว้ เมื่อวันที่ 13 มิถุนายน พ.ศ. 2510 ในปัจจุบันช่วงคลองลัดบางกรวย (หมายเลข ๒ ในภาพ) ถือว่าเป็นส่วนหนึ่งคลองบางกอกน้อยไปด้วย รวมถึงคลองอ้อมนนท์…',
  'Khlong Bangkok Noi (Thai: คลองบางกอกน้อย, pronounced [kʰlɔ̄ːŋ bāːŋ.kɔ̀ːk nɔ́ːj], lit. ''Small Bangkok Canal'') is a khlong (lit. ''canal'') in Bangkok; its name is the origin of the name Bangkok Noi District.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%84%E0%B8%A5%E0%B8%AD%E0%B8%87%E0%B8%9A%E0%B8%B2%E0%B8%87%E0%B8%81%E0%B8%AD%E0%B8%81%E0%B8%99%E0%B9%89%E0%B8%AD%E0%B8%A2","license":"CC BY-SA 4.0"}'::jsonb,
