  'Central',
  'C',
  null,
  null,
  14.311931944444,
  101.320935,
  '{"name":"Wikidata","url":"https://www.wikidata.org/wiki/Q16140439","property":"P625","confidence":100}'::jsonb,
  'industrial site',
