do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'71709235-fbe6-59d7-6be0-a076f543e3ae',
  'ko-kret',
  'เกาะเกร็ด',
  'Ko Kret',
  'เกาะเกร็ด เป็นเกาะแม่น้ำในแม่น้ำเจ้าพระยาตอนล่าง และมีฐานะเป็นตำบลหนึ่งในท้องที่อำเภอปากเกร็ด จังหวัดนนทบุรี มีเนื้อที่ประมาณ 4.2 ตารางกิโลเมตรหรือ 2,625 ไร่ เป็นที่อยู่ของชาวไทยเชื้อสายมอญที่มีอาชีพปั้นเครื่องปั้นดินเผาเป็นส่วนใหญ่ เกาะเกร็ดเกิดจากการขุดคลองลัดแม่น้ำเจ้าพระยาเมื่อปี พ.ศ. 2265 ในรัชสมัยสมเด็จพระที่นั่งท้ายสระ คลองลัดดังกล่าวเรียกว่า "คลองลัดเกร็ดน้อย" หรือ "คลองเตร็ดน้อย" ดังปรากฏในพระราชพงศาวดารกรุงสยามฉบับบริติชมิวเซียมตอนหนึ่งว่า "...ในปีขาล จัตวาศก ทรงพระกรุณาโปรดให้พระธนบุรีเป็นแม่กอง เกณฑ์พลนิกายคนหัวเมืองปากใต้ให้ได้คน ๑๐,๐๐๐ เศษ ให้ขุดคลองเตร็ดน้อย ลัดคุ้งบางบัวทองนั้นคดอ้อมนัก ขุดลัดตัดให้ตรง พระธนบุรีรับสั่งแล้วถวายบังคมลามา ให้เกณฑ์พลนิกายในบรรดาหัวเมืองปากใต้ได้คน ๑๐,๐๐๐ เศษ ให้ขุดคลองเตร็ดน้อยนั้นลึก ๖ ศอก กว้าง ๓ วา ยาวทางไกลได้ ๒๙ เส้นเศษ ขุดเดือนเศษจึ่งแล้ว..."…',
  'Ko Kret (Thai: เกาะเกร็ด, pronounced [kɔ̀ʔ krèt] , Mon : တ္ကအ်ကြေတ် ) is a small island in the Chao Phraya River in Nonthaburi province, Thailand. It is around 3 km (1.9 mi) long and 3 km (1.9 mi) wide with an area of over 4.2 square kilometers. It has seven main villages, the largest and most populous being Ban Mon. The island is best known for Thai-Mon people who make pottery for a living. The island is served by ferries.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B9%80%E0%B8%81%E0%B8%B2%E0%B8%B0%E0%B9%80%E0%B8%81%E0%B8%A3%E0%B9%87%E0%B8%94","license":"CC BY-SA 4.0"}'::jsonb,
