do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'dc92d330-db3b-5305-8d80-e12b56175a98',
  'ko-lanta-yai',
  'เกาะลันตาใหญ่',
  'Ko Lanta Yai',
  'เกาะลันตาใหญ่ เป็นเกาะในอุทยานแห่งชาติหมู่เกาะลันตา ในตำบลเกาะลันตาใหญ่ อำเภอเกาะลันตา จังหวัดกระบี่ เป็นที่ตั้งของที่ว่าการอำเภอและที่ทำการอุทยาน มีสภาพเป็นทิวเขาสลับซับซ้อน ปกคลุมด้วยป่าที่สมบูรณ์ ชื่อ "ลันตา" สันนิษฐานว่าเพี้ยนมาจากคำว่า "ลันตาส" ซึ่งเป็นภาษาชวา แปลว่า ที่ย่างปลา เพราะในอดีตเป็นที่ที่ชาวเรือชวามักมาหยุดพักและย่างปลาเป็นอาหาร เกาะลันตาใหญ่มียาวประมาณ 30 กิโลเมตร กว้างประมาณ 6 กิโลเมตร มีชายหาดยาวเรียงรายต่อเนื่องกันถึง 13 หาดทางฝั่งตะวันตก ทั้งหาดหินและหาดทราย ส่วนทางฝั่งตะวันออกคือ ชุมชนโบราณ ชื่อ บ้านศรีรายา ซึ่งตั้งมากว่าร้อยปี สร้างบ้านเรือนแถวไม้หน้าแคบที่ยื่นยาวลึกออกไปในทะเล ชาวเลที่อาศัยอยู่บนเกาะ ชาวบ้านส่วนใหญ่บนเกาะลันตานับถือศาสนาอิสลาม และที่บ้านสังกะอู้ยังคงความเป็นอยู่ตามวัฒนธรรมและประเพณีดั้งเดิมไว้อยู่ คือประเพณีลอยเรือ เพื่อสะเดาะเคราะห์และความเป็นสิริมงคล ในคืนวันเพ็ญเดือน 6 และ เดือน 11 ฤดูท่องเที่ยวอยู่ระหว่างเดือนพฤศจิกายนถึงเดือนพฤษภาคม',
  'Ko Lanta Yai (Thai: เกาะลันตาใหญ่, lit. ''Big Lanta Island'') is an island in the Strait of Malacca off the west coast of Thailand, between the Phi Phi Islands and the mainland. It is administratively part of Krabi Province, most of which is on the mainland. Together with neighboring Ko Lanta Noi (Small Lanta Island), which forms the Ko Lanta archipelago, and several other islands, it forms the amphoe of Ko Lanta District.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B9%80%E0%B8%81%E0%B8%B2%E0%B8%B0%E0%B8%A5%E0%B8%B1%E0%B8%99%E0%B8%95%E0%B8%B2%E0%B9%83%E0%B8%AB%E0%B8%8D%E0%B9%88","license":"CC BY-SA 4.0"}'::jsonb,
