insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'f92fdb36-3d88-596e-4af7-ab5388b9a96f',
  'ko-muk',
  'เกาะมุก',
  'Ko Muk',
  'เกาะมุก บ้างเขียนว่า เกาะมุกต์ ตั้งอยู่ในเขตอุทยานแห่งชาติหาดเจ้าไหม ในท้องที่ตำบลเกาะลิบง อำเภอกันตัง จังหวัดตรัง เป็นเกาะที่มีความใหญ่เป็นอันดับ 3 ของจังหวัดตรัง มีความยาวของเกาะในแนวเหนือใต้ ประมาณ 4.15 กิโลเมตร ความกว้างในแนวตะวันออกตะวันตก ประมาณ 3.8 กิโลเมตร มีพื้นที่รวมทั้งสิ้น 7.7 ตารางกิโลเมตร มีหมู่บ้าน 1 หมู่บ้าน คือ บ้านเกาะมุก ซึ่งได้กันแนวเขตออกจากพื้นที่อุทยานแห่งชาติ ร้อยละ 80 ของพื้นที่ทั้งหมด ภูเขามีจุดสูงสุดประมาณ 300 เมตร จากระดับน้ำทะเลปานกลาง โดยวางตัวในแนวเหนือใต้ มีประชากรอาศัยอยู่ประมาณ 1500 คน เป็นมุสลิมประมาณร้อยละ 80 อาชีพหลักของคนบนเกาะ ได้แก่ ประมงพื้นบ้าน โดยเฉพาะลอบหมึก ที่เกาะมุกยังมีการดำหาหอยมุกกันบ้าง เกาะมุกมีถ้ำมรกต (Morakot Cave) อยู่ทางทิศตะวันตกของเกาะ เป็นถ้ำที่มีโพรงถ้ำเล็ก ๆ ที่จะเข้าไปได้ก็ต้องรอช่วงน้ำลดเท่านั้น เมื่อเข้าไปในถ้ำราว 80 เมตร จะถึงปากถ้ำอีกด้าน ซึ่งมีหาดทรายขาวท่ามกลางหน้าผาสูงชัน…',
  'Ko Muk is a island in Trang, Thailand. Coordinates and photography are sourced from Wikidata and Wikimedia Commons.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B9%80%E0%B8%81%E0%B8%B2%E0%B8%B0%E0%B8%A1%E0%B8%B8%E0%B8%81","license":"CC BY-SA 4.0"}'::jsonb,
