  'Trang',
  'ตรัง',
  'South',
  'C',
  null,
  null,
  7.3733119444444,
  99.295516111111,
  '{"name":"Wikidata","url":"https://www.wikidata.org/wiki/Q14221110","property":"P625","confidence":100}'::jsonb,
  'island',
  'unknown',
