do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'7be5dec9-54da-5255-c40c-1cc577b21240',
  'maha-chai-railway-station',
  'สถานีรถไฟมหาชัย',
  'Maha Chai railway station',
  'สถานีรถไฟมหาชัย เป็นสถานีรถไฟระดับ 1 ของทางรถไฟสายแม่กลอง ตั้งอยู่ถนนสุขาภิบาล ตำบลมหาชัย อำเภอเมืองสมุทรสาคร จังหวัดสมุทรสาครห่างจากสถานีรถไฟวงเวียนใหญ่ 31 กิโลเมตร การรถไฟฯ จัดเดินขบวนรถวันละ 34 ขบวน (เที่ยวไป 17 ขบวน และเที่ยวกลับ 17 ขบวน) สถานีรถไฟมหาชัยเป็นสถานีปลายทางของเส้นทางช่วงวงเวียนใหญ่-มหาชัย ผู้โดยสารที่ต้องการโดยสารรถไฟต่อไปยังจังหวัดสมุทรสงครามจะต้องลงจากขบวนรถและเดินตามถนนเป็นระยะทาง 500 เมตร จากนั้นต่อเรือข้ามฟากไปที่ท่าฉลอมเพื่อขึ้นรถไฟช่วงต่อที่สถานีรถไฟบ้านแหลม มีปลายทางที่สถานีรถไฟแม่กลอง ระยะทาง 33 กิโลเมตร',
  'Mahachai railway station is a railway station located in Mahachai subdistrict, Mueang Samut Sakhon district, Samut Sakhon province. It is a class 1 railway station and is the main railway station of Samut Sakhon. As there is no bridge connecting the two separate sections of the Maeklong Railway, passengers continuing onwards in either direction must use a ferry to cross to Ban Laem railway station on the opposite side of the Tha Chin River. Currently, 34 rail services operate at the station.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%AA%E0%B8%96%E0%B8%B2%E0%B8%99%E0%B8%B5%E0%B8%A3%E0%B8%96%E0%B9%84%E0%B8%9F%E0%B8%A1%E0%B8%AB%E0%B8%B2%E0%B8%8A%E0%B8%B1%E0%B8%A2","license":"CC BY-SA 4.0"}'::jsonb,
  'samut-sakhon',
  'Samut Sakhon',
  'สมุทรสาคร',
  'Central',
  'B',
  null,
  null,
