insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'4d89c0df-cbf2-543b-8cb1-0dde794db978',
  'maha-chesadabodindranusorn-bridge',
  'สะพานมหาเจษฎาบดินทรานุสรณ์',
  'Maha Chesadabodindranusorn Bridge',
  'สะพานมหาเจษฎาบดินทรานุสรณ์ เป็นสะพานข้ามแม่น้ำเจ้าพระยาในเขตอำเภอเมืองนนทบุรี จังหวัดนนทบุรี เชื่อมพื้นที่ตำบลสวนใหญ่ (ฝั่งตะวันออก) เข้ากับตำบลบางศรีเมือง (ฝั่งตะวันตก) โดยเริ่มต้นจากปลายสะพานทางแยกต่างระดับบนถนนนนทบุรี 1 ใกล้โรงเรียนศรีบุณยานนท์ ข้ามแม่น้ำเจ้าพระยาในท้องที่หมู่ที่ 2 ตำบลสวนใหญ่ ทางด้านใต้ของชุมชนตลาดขวัญและท่าเรือพิบูลสงคราม 4 โดยวางตัวไปทางทิศตะวันตกเฉียงใต้และขึ้นฝั่งตะวันตกบริเวณปากคลองอ้อมฝั่งใต้ ระหว่างศาลเจ้าพ่อหลักเมือง (เดิม) ที่อยู่ทางเหนือกับอุทยานเฉลิมกาญจนาภิเษกที่อยู่ทางใต้ ในท้องที่หมู่ที่ 3 บ้านท่าน้ำนนท์ ตำบลบางศรีเมือง เส้นทางจากนั้นเป็นแนวถนนตัดใหม่ซึ่งมุ่งไปสู่ทางแยกต่างระดับที่ถนนราชพฤกษ์',
  'Maha Chesadabodindranusorn Bridge (Thai: สะพานมหาเจษฎาบดินทรานุสรณ์, RTGS: Saphan Mahachetsadabodinthranuson, pronounced [sa.pʰāːn ma.hǎː.t͡ɕèːt.sa.dāː.bɔ̄(ː).dīn.tʰrāː.nú.sɔ̌ːn]) is an extradosed bridge in area of Mueang Nonthaburi District in Nonthaburi Province, Thailand, over the Chao Phraya River. The bridge is the first extradosed bridge in Thailand. It is located between Phra Nangklao Bridge (upstream) and Rama V Bridge (downstream), connects Nonthaburi 1 Road, on the east side of the river, and Bang Si Mueang - Wat Bot Don Phrom Road and Ratchaphruek Road, on the west side of the river. The bridge was named after King Nangklao, one of whose titles before his accession to the throne was "Prince Chesadabodin". The project has a total length of approximately 4.3 kilometres (2.7 mi), consisting of an interchange at Nonthaburi 1 Road, a 6-lane extradosed concrete bridge with 200…',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%AA%E0%B8%B0%E0%B8%9E%E0%B8%B2%E0%B8%99%E0%B8%A1%E0%B8%AB%E0%B8%B2%E0%B9%80%E0%B8%88%E0%B8%A9%E0%B8%8E%E0%B8%B2%E0%B8%9A%E0%B8%94%E0%B8%B4%E0%B8%99%E0%B8%97%E0%B8%A3%E0%B8%B2%E0%B8%99%E0%B8%B8%E0%B8%AA%E0%B8%A3%E0%B8%93%E0%B9%8C","license":"CC BY-SA 4.0"}'::jsonb,
