insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'41147743-a4a5-5927-f569-c87d4a661ffa',
  'mbk-center',
  'เอ็มบีเค เซ็นเตอร์',
  'MBK Center',
  'ศูนย์การค้าเอ็มบีเค เซ็นเตอร์ (อังกฤษ: MBK Center) เดิมชื่อ ศูนย์การค้ามาบุญครอง เซ็นเตอร์ (อังกฤษ: Mahbunkhrong Center) เป็นศูนย์การค้าขนาดใหญ่ในเขตปทุมวัน กรุงเทพมหานคร เปิดให้บริการในชื่อ ศูนย์การค้ามาบุญครอง เซ็นเตอร์ เมื่อวันที่ 7 กุมภาพันธ์ พ.ศ. 2528 ก่อนที่จะเปลี่ยนชื่อศูนย์การค้าเป็นเอ็มบีเค เซ็นเตอร์ และ ดำเนินงานโดยบริษัท เอ็มบีเค จำกัด (มหาชน) บนพื้นที่ของจุฬาลงกรณ์มหาวิทยาลัย ภายในเป็นบริเวณมุมตะวันตกเฉียงใต้ของสี่แยกปทุมวัน ในย่านสยาม มีพื้นที่ใช้ทั้งหมด 270,685.57 ตารางเมตร ซึ่งส่วนหนึ่งจัดเป็นพื้นที่เช่าค้าขาย จำนวนกว่า 2,500 ร้านค้า โดยมีสินค้าและบริการเพื่อรองรับนักท่องเที่ยวทั้งชาวไทย และชาวต่างชาติ นับเป็นศูนย์การค้าแห่งแรกของประเทศไทยที่มีศูนย์อาหารฟู้ดคอร์ท',
  'MBK Center (Thai: เอ็มบีเค เซ็นเตอร์), also known by its former name as Mahbunkhrong (Thai: มาบุญครอง, RTGS: Mabunkhrong, pronounced [māː.būn.kʰrɔ̄ːŋ]), is a large shopping mall in Siam area, Bangkok, Thailand. At eight storeys, the center contains around 2,000 shops, restaurants and service outlets. In 2009, MBK Center management reported daily visitor numbers of more than 100,000, half of whom were young Thai people and a third foreign visitors.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B9%80%E0%B8%AD%E0%B9%87%E0%B8%A1%E0%B8%9A%E0%B8%B5%E0%B9%80%E0%B8%84%E0%B9%80%E0%B8%8B%E0%B9%87%E0%B8%99%E0%B9%80%E0%B8%95%E0%B8%AD%E0%B8%A3%E0%B9%8C","license":"CC BY-SA 4.0"}'::jsonb,
