insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'f8cbd57d-38fc-56fc-3712-6e61abf31f85',
  'mu-ko-ang-thong-national-park',
  'อุทยานแห่งชาติหมู่เกาะอ่างทอง',
  'Mu Ko Ang Thong National Park',
  'อุทยานแห่งชาติหมู่เกาะอ่างทอง เป็นอุทยานแห่งชาติทางทะเลที่มีลักษณะเป็นหมู่เกาะในอ่าวไทยประกอบด้วยเกาะต่าง ๆ 42 เกาะ ได้แก่ เกาะพะลวย เกาะวัวตาหลับ เกาะแม่เกาะ เกาะสามเส้า เกาะหินดับ เกาะนายพุด และเกาะไผ่ลวก เป็นต้น ตั้งอยู่ในท้องที่ตำบลอ่างทอง อำเภอเกาะสมุย จังหวัดสุราษฎร์ธานี ครอบคลุมพื้นที่ 102 ตารางกิโลเมตร เป็นพื้นน้ำประมาณ 84 ตารางกิโลเมตร หรือประมาณ 82 เปอร์เซ็นต์ของพื้นที่ทั้งหมด ได้รับการประกาศจัดตั้งเป็นอุทยานแห่งชาติเมื่อวันที่ 12 พฤศจิกายน พ.ศ. 2523 อุทยานแห่งชาติหมู่เกาะอ่างทองได้รับรางวัลอุทยานแห่งชาติสีเขียว (Green National Parks) ระดับทอง (ดีเยี่ยม) ประจำปี 2563',
  'Mu Ko Ang Thong is a marine national park in the Gulf of Thailand in Surat Thani Province. It covers 42 islands in a total area of 63,750 rai ~ 102 square kilometres (39 sq mi), of which about 50 square kilometres (19 sq mi) are land and the rest is water. The park was established on 12 November 1980. The northern tip of Ko Phaluai is also part of the marine park. There is a ranger station, bungalows, a shop, and a restaurant at Ao Phi Beach on Ko Wua Talap. The name "Ang Thong" (Thai: อ่างทอง) means ''bowl of gold''. "Mu Ko" (หมู่เกาะ) simply means ''group of islands''. Since 2002 the park has been registered as Ramsar site number 1184.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%AD%E0%B8%B8%E0%B8%97%E0%B8%A2%E0%B8%B2%E0%B8%99%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B8%AB%E0%B8%A1%E0%B8%B9%E0%B9%88%E0%B9%80%E0%B8%81%E0%B8%B2%E0%B8%B0%E0%B8%AD%E0%B9%88%E0%B8%B2%E0%B8%87%E0%B8%97%E0%B8%AD%E0%B8%87","license":"CC BY-SA 4.0"}'::jsonb,
