do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'bac45c99-b35e-5311-1e2b-07b7eeba9599',
  'nakhon-pathom-railway-station',
  'สถานีรถไฟนครปฐม',
  'Nakhon Pathom railway station',
  'สถานีนครปฐม (อังกฤษ: Nakhon Pathom Station) เป็นสถานีรถไฟชั้น 1 ของทางรถไฟสายใต้ และส่วนต่อขยายในอนาคตรถไฟฟ้าชานเมืองสายสีแดงอ่อน ตั้งอยู่อำเภอเมืองนครปฐม จังหวัดนครปฐม อยู่ห่างจากสถานีรถไฟธนบุรีเป็นระยะทาง 48.12 กิโลเมตร และอยู่ห่างจากสถานีรถไฟกรุงเทพเป็นระยะทาง 64.17 กิโลเมตร อยู่ระหว่าง สถานีต้นสำโรงและ ที่หยุดรถพระราชวังสนามจันทร์',
  'Nakhon Pathom railway station is a railway station located in Phra Pathom Chedi subdistrict, Mueang Nakhon Pathom district, and is located 48.126 km (29.9 mi) from Thon Buri railway station. It is a class 1 railway station and is the main railway station of Nakhon Pathom province. The station is not far from Phra Pathom Chedi which is a famous landmark of the province. The station opened in June 1903 as part of the first phase of the Southern Line construction between Thon Buri Station to Phetchaburi Station and was originally named "Phra Pathom" station. During the 2011 Thailand floods, Nakhon Pathom Station was the terminus for most train services instead of Bangkok railway station as some sections between Nakhon Pathom and Bangkok were flooded. The station is the terminus of the Thon Buri - Nakhon Pathom SRT Light Red Line feeder services. Until 2024, Nakhon Pathom station was…',
