do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'16f61ba2-09bc-57ea-b66b-0e0b0541ccb3',
  'phra-maha-chedi-chai-mongkhon',
  'พระมหาเจดีย์ชัยมงคล',
  'Phra Maha Chedi Chai Mongkhon',
  'วัดถ้ำผาน้ำทิพย์ เป็นวัดราษฎร์สังกัดคณะสงฆ์ฝ่ายธรรมยุติกนิกาย ตั้งอยู่ในตำบลผาน้ำย้อย อำเภอหนองพอก จังหวัดร้อยเอ็ด เป็นพุทธอุทยานมีเนื้อที่ 2,500 ไร่ วัดถ้ำผาน้ำทิพย์ หรือ วัดผาน้ำทิพย์ หรือ วัดผาน้ำทิพย์เทพประสิทธิ์วนาราม มูลเหตุในการสร้างวัด เมื่อปี พ.ศ. 2493–2494 ท่านพระอาจารย์ศรี มหาวีโร ได้ธุดงค์มาเจริญสมถกัมมัฎฐานบริเวณนี้ ต่อมา พ.ศ. 2493–2500 ท่านพระอาจารย์ได้พาพระภิกษุซึ่งเป็นศิษย์มาปฏิบัติธรรม บริเวณนี้แต่เดิมเป็น ป่าดงดิบสภาพป่า สวยงามตามธรรมชาติ มีสัตว์ป่านานาชนิดอาศัยอยู่ ได้ชื่อว่า ผาน้ำย้อย เพราะมีลักษณะเป็นนหน้าผาสูงชัน มีน้ำตกไหลหยดย้อยตลอดเวลาทั้งปี เมื่อชาวบ้านเจ็บป่วยก็จะได้น้ำ ณ จุดนี้ไปดื่มกิน เพื่อรักษาโรคตามความเชื่อจึงเป็นสาเหตุหนึ่งที่ได้ชื่อว่า "วัดผาน้ำทิพย์เทพประสิทธิ์วนาราม" ต่อมาสภาพป่าถูกทำลายเนื่องจากประชาชนได้ลักลอบตัดไม้บางกลุ่มก็เข้าไปทำไม้แปรรูปขาย ทางราชการจึงได้พิจารณาเห็นความสำคัญของพุทธศาสนา ดังนั้นในปี พ.ศ. 2517 ประสิทธิ์ ทองใบใหญ่…',
  'Phra Maha Chedi Chai Mongkhon is a temple in Roi Et, Thailand. Coordinates and photography are sourced from Wikidata and Wikimedia Commons.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%9E%E0%B8%A3%E0%B8%B0%E0%B8%A1%E0%B8%AB%E0%B8%B2%E0%B9%80%E0%B8%88%E0%B8%94%E0%B8%B5%E0%B8%A2%E0%B9%8C%E0%B8%8A%E0%B8%B1%E0%B8%A2%E0%B8%A1%E0%B8%87%E0%B8%84%E0%B8%A5","license":"CC BY-SA 4.0"}'::jsonb,
  'roi-et',
  'Roi Et',
  'ร้อยเอ็ด',
  'Northeast',
  'C',
