  'Surin',
  'สุรินทร์',
  'Northeast',
  'C',
  null,
  null,
  14.944919444444,
  103.79867777778,
  '{"name":"Wikidata","url":"https://www.wikidata.org/wiki/Q1284947","property":"P625","confidence":100}'::jsonb,
