insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'e9240965-01dc-5527-5b18-a7b361eca665',
  'royal-city-avenue',
  'รอยัล ซิตี้ อเวนิว',
  'Royal City Avenue',
  'อาร์ซีเอ หรือชื่อเต็มว่า รอยัล ซิตี้ อเวนิว (อังกฤษ: RCA, Royal City Avenue) เป็นแหล่งย่านสถานบันเทิง อยู่ในเขตห้วยขวาง และอาร์ซีเอเป็นถนนสายเชื่อมระหว่างถนนพระราม 9 กับถนนเพชรบุรี มีชื่อเสียงทางด้านเป็นแหล่งสถานบันเทิงมากมาย ไม่ว่าจะเป็น บาร์ไนท์คลับ และ งานแสดงดนตรีต่าง ๆ โดยมากนักท่องเที่ยวจะเป็นวัยรุ่น ส่วนใหญ่เป็นนักศึกษามหาวิทยาลัย โครงการรอยัล ซิตี้ อเวนิว เนื้อที่ 62 ไร่ (25,000 va) มีบริษัท นารายณ์ร่วมพิพัฒน์ จำกัด ของกลุ่มธนาคารกรุงเทพเป็นผู้บริหาร โดยเช่าที่ดิน 30 ปี จากการรถไฟแห่งประเทศไทย โดยสัญญาเช่าสิ้นสุดเมื่อเดือนตุลาคม 2565 ที่ผ่านมา การรถไฟแห่งประเทศไทยได้ต่อสัญญาเช่าให้เป็นการชั่วคราวแบบปีต่อปี ระหว่างรอให้บริษัท เอสอาร์ที แอสเสท จำกัด ศึกษารูปแบบพัฒนาโครงการและเปิดประมูลใหม่ สัญญาเช่าชั่วคราวจะสิ้นสุดในปี 2567',
  'Royal City Avenue or RCA is one of Bangkok''s largest entertainment and clubbing areas. Located on in Huai Khwang district, RCA is a long street located between Rama IX Road and Phetchaburi Road. It contains a multitude of bars, nightclubs and live music venues. RCA is owned and operated by Narai Ruamphiphat Co., Ltd. The Royal City Avenue project, covering 62 rai (25,000 square wah), is managed by Narai Ruampipat Co., Ltd., a subsidiary of the Bangkok Bank Group, on a 30-year lease from the State Railway of Thailand. The lease expired in October 2022. The State Railway of Thailand has temporarily renewed the lease on a year-to-year basis while SRT Asset Co., Ltd. conducts a development study and opens new bids. The temporary lease expires in 2024.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%AD%E0%B8%B2%E0%B8%A3%E0%B9%8C%E0%B8%8B%E0%B8%B5%E0%B9%80%E0%B8%AD_(%E0%B8%AA%E0%B8%96%E0%B8%B2%E0%B8%99%E0%B8%9A%E0%B8%B1%E0%B8%99%E0%B9%80%E0%B8%97%E0%B8%B4%E0%B8%87)","license":"CC BY-SA 4.0"}'::jsonb,
