do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'61643139-c64d-591e-4c06-d57a94b0f3d3',
  'wat-ahong-silawat',
  'วัดอาฮงศิลาวาส',
  'Wat Ahong Silawat',
  'วัดอาฮงศิลาวาส เป็นวัดราษฎร์สังกัดคณะสงฆ์ฝ่ายธรรมยุติกนิกาย ตั้งอยู่ในตำบลไคสี อำเภอเมืองบึงกาฬ จังหวัดบึงกาฬ วัดอาฮงศิลาวาส แต่เดิมเรียกว่า วัดป่าเลไลย สร้างโดยหลวงพ่อลุน เมื่อหลวงพ่อมรณภาพ วัดจึงถูกทิ้งร้าง จนกระทั่งเมื่อ พ.ศ. 2517 ท่านเจ้าคุณนิเทศศาสนคุณ (หลวงพ่อมหาสมานสิริปัญโญ) ผ่านมาพบวัดที่มีสภาพสงบร่มรื่น อยู่ติดริมโขงนี้ จึงได้ทำการปฏิสังขรณ์วัด และตั้งชื่อวัดใหม่ว่า "วัดอาฮงศิลาวาส" ตามชื่อแก่งอาฮง ตั้งเป็นวัดเมื่อ พ.ศ. 2480 ได้รับพระราชทานวิสุงคามสีมาเมื่อวันที่ 20 พฤษภาคม พ.ศ. 2548 วิหารประดิษฐาน พระพุทธคุวานันท์ศาสดา หล่อด้วยทองเหลือง ลักษณะคล้ายกับพระพุทธชินราช เป็นพระพุทธรูปขนาดหน้าตักกว้าง 4 เมตร สูง 7 เมตร น้ำหนัก 20 ตัน มีความเชื่อกันว่าลำน้ำโขงในบริเวณหน้าอุโบสถของวัดเป็นจุดที่ลึกที่สุดในแม่น้ำโขง เรียกว่า "สะดือแม่น้ำโขง" เคยมีการวัดความลึกโดยใช้เชือกผูกกับก้อนหินหย่อนลงไปได้ลึกถึง 200 เมตร นอกจากนี้ยังมีสวนหินที่บ่งบอกลักษณะกายภาพของพื้นที่ริมโขงเมื่อล้านปีก่อน',
  'Wat Ahong Silawat is a temple in Bueng Kan, Thailand. Coordinates are sourced from Wikidata.',
