insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'3c079d5e-1df6-5ab2-3306-b592a0d148a1',
  'wat-arun',
  'วัดอรุณราชวรารามราชวรมหาวิหาร',
  'Wat Arun',
  'วัดอรุณราชวราราม หรือเรียกสั้น ๆ ว่า วัดอรุณ หรือ วัดแจ้ง เป็นพุทธศาสนสถานในประเทศไทย มีสถานะเป็นพระอารามหลวงชั้นเอก ชนิดราชวรมหาวิหาร ตั้งอยู่ริมฝั่งแม่น้ำเจ้าพระยา เขตบางกอกใหญ่ กรุงเทพมหานคร มีประวัติยาวนานตั้งแต่สมัยกรุงศรีอยุธยา เดิมชื่อ วัดบางมะกอก ต่อมาในสมัยสมเด็จพระเจ้ากรุงธนบุรีแห่งกรุงธนบุรี ได้เปลี่ยนชื่อเป็นวัดแจ้ง เนื่องจากการยกทัพผ่านมาหน้าวัดในยามรุ่งอรุณ และเมื่อพระบาทสมเด็จพระพุทธเลิศหล้านภาลัยทรงบูรณปฏิสังขรณ์วัดใหม่ จึงทรงพระราชทานนามวัดว่า "วัดอรุณราชวราราม" เพื่อเป็นวัดประจำรัชกาลอีกด้วย พระปรางค์วัดอรุณราชวรารามราชวรมหาวิหารเป็นสถาปัตยกรรมไทยที่โดดเด่นที่สุดของวัด ประกอบด้วยพระปรางค์ประธานสูง 67 เมตร และพระปรางค์รองขนาดเล็ก 4 องค์ตั้งอยู่รอบทิศทั้งสี่ โดยพระปรางค์องค์เดิมสร้างขึ้นในสมัยกรุงศรีอยุธยา และได้รับการสร้างต่อเติมให้สูงขึ้นโดยพระบาทสมเด็จพระพุทธเลิศหล้านภาลัยและพระบาทสมเด็จพระนั่งเกล้าเจ้าอยู่หัว โดยมีการประดับด้วยกระเบื้องเคลือบและชามเบญจรงค์ที่งดงาม…',
  'Wat Arun Ratchawararam Ratchawaramahawihan (Thai: วัดอรุณราชวราราม ราชวรมหาวิหาร ) or Wat Arun (Thai pronunciation: [wát ʔarun], "Temple of Dawn") is a Buddhist temple (wat) in the Bangkok Yai district of Bangkok, Thailand. It is situated in Thonburi on the west bank of the Chao Phraya River. The temple derives its name from the Hindu god Aruṇa, often personified as the rays of the rising sun. Built with a fusion of Indian influences, incorporating elements of both Hindu and Buddhist symbolism, as well as reflecting Siamese tradition and identity. Wat Arun is among the best known of Thailand''s landmarks. Although the temple has existed since at least the 17th century, its distinctive prang (spire) was built in the early 19th century during the reigns of Rama II and Rama III.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B8%AD%E0%B8%A3%E0%B8%B8%E0%B8%93%E0%B8%A3%E0%B8%B2%E0%B8%8A%E0%B8%A7%E0%B8%A3%E0%B8%B2%E0%B8%A3%E0%B8%B2%E0%B8%A1%E0%B8%A3%E0%B8%B2%E0%B8%8A%E0%B8%A7%E0%B8%A3%E0%B8%A1%E0%B8%AB%E0%B8%B2%E0%B8%A7%E0%B8%B4%E0%B8%AB%E0%B8%B2%E0%B8%A3","license":"CC BY-SA 4.0"}'::jsonb,
