insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'5bffbe28-9a61-507f-7416-74c2be4b9ae6',
  'wat-bamphen-chin-phrot',
  'วัดบำเพ็ญจีนพรต',
  'Wat Bamphen Chin Phrot',
  'วัดบำเพ็ญจีนพรต (จีน: 永福寺) สังกัดคณะสงฆ์จีนนิกายแห่งประเทศไทย เป็นปฐมสังฆารามฝ่ายมหายานจีนนิกาย (นิกายฌาณ สาขาหลินฉี) ตั้งอยู่ในตรอกวัดกันมาตุยาราม ถนนเยาวราช แขวงสัมพันธวงศ์ เขตสัมพันธวงศ์ กรุงเทพฯ สภาพที่ตั้งวัดเป็นพื้นที่กลางเมือง ติดถนนเยาวราช ล้อมรอบด้วยอาคารพาณิชย์ โดยรอบส่วนใหญ่มีความสูง 3 ชั้นขึ้นไป บริเวณใกล้เคียงเป็นวัดกันมาตุยารามฝ่ายธรรมยุตินิกาย และวัดกุศลสมาครฝ่ายอนัมนิกาย (วัดญวน)',
  'Wat Bamphen Chin Phrot (Thai: วัดบำเพ็ญจีนพรต; Chinese: 永福寺; pinyin: Yǒngfú Sì) or familiarly known in Teochew Yong Hok Yi (ย่งฮกยี่) is a Chinese temple of the Mahāyāna sect in Thailand, located on Soi Yaowarat 8 (Trok Tao), Samphanthawong Subdistrict, Samphanthawong District, Bangkok. This temple has many interesting features, because it is one of the oldest Chinese temples in Thailand (old than nearby Wat Mangkon Kamalawat), including the only temple located on Yaowarat Road and can be considered as the smallest temple in the country, because it is only five storey shophouse. The temple was originally Avalokiteśvara''s place of worship founded by overseas Chinese who live in Siam (Thailand at that time) since 1795 (corresponding to the reign of Qianlong Emperor). Later abandoned, Chinese monk named Sok Heng was renovated in 1867 and received a Thai name from King Chulalongkorn (Rama…',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B8%9A%E0%B8%B3%E0%B9%80%E0%B8%9E%E0%B9%87%E0%B8%8D%E0%B8%88%E0%B8%B5%E0%B8%99%E0%B8%9E%E0%B8%A3%E0%B8%95","license":"CC BY-SA 4.0"}'::jsonb,
