insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'ab90752e-c7b2-5ee0-d6aa-f6dd33bca3df',
  'wat-chalong',
  'วัดฉลอง',
  'Wat Chalong',
  'วัดไชยธาราราม เดิมชื่อ วัดฉลอง ตั้งอยู่ อำเภอเมืองภูเก็ต จังหวัดภูเก็ต ห่างจากอำเภอเมืองภูเก็ต ระยะทาง 8 กิโลเมตร ทางหลวงหมายเลข 4021 ผ่านสนามกีฬาสุระกุล เลี้ยวซ้ายไปห้าแยกฉลอง สมัยรัชกาลที่ 5 พระครูวิสุทธิวงศาจารย์ญาณมุนี (แช่ม) เป็นเจ้าอาวาส มีชื่อเสียงการปรุงสมุนไพร และรักษาโรค เข้าเฝือกผู้ป่วยกระดูกหัก ปัจจุบันพระครูวิสุทธิวงศาจารย์ญาณมุนีได้มรณภาพแล้ว เจ้าอาวาสวัดสัมโพธิหาร (วัดสัมโพธิหาร เดิมชื่อ วัดป่าอรัญนิรมล ประเทศศรีลังกา) ได้กล่าวว่า พระบรมสารีริกธาตุที่ได้มอบให้วัดไชยธาราราม เคยอยู่ในเจดีย์ของเมืองอนุราชปุระ เมืองหลวงเดิมของศรีลังกา มีอายุกว่า 2,200 ปี มาแล้ว วโรกาสที่พระบาทสมเด็จพระเจ้าอยู่หัวทรงเจริญพระชนมายุครบ 72 พรรษา พระเถระชั้นผู้ใหญ่ของศรีลังกาคือ พระปิยะทัสสะ นายะกะเถโร และพระกุศลาธรรมา แห่งวัดสัมโพธิวิหาร ได้มีหนังสือกราบทูลสมเด็จพระญาณสังวร สมเด็จพระสังฆราชสกลมหาสังฆปรินายก เสด็จเยือนศรีลังกา เพื่อรับการถวายพระบรมสารีริกธาตุ วันที่ 20 มีนาคม พ.ศ.…',
  'The most important of the 29 buddhist temples of Phuket is Wat Chalong (Thai: วัดฉลอง, pronounced [wát t͡ɕʰā.lɔ̌ːŋ]) or officially Wat Chaiyathararam (วัดไชยธาราราม, [wát t͡ɕʰāj.jáʔ.tʰāː.rāː.rāːm]), located in the Chalong Subdistrict, Mueang Phuket District. It is dedicated to two highly venerable monks, Luang Pho Chaem (หลวงพ่อแช่ม, [lǔa̯ŋ pʰɔ̂ː t͡ɕʰɛ̂m]) and Luang Pho Chuang (หลวงพ่อช่วง, [lǔa̯ŋ pʰɔ̂ː t͡ɕʰûa̯ŋ]), who led the citizens of Chalong Subdistrict fighting against the Chinese rebellion in 1876 and with their knowledge of herbal medicine helped the injured. The large market at Wat Chalong extends into the grounds of the temple and features amplified pop music and Thai-fighting advertisements. The temple sells trinkets to visitors and the monks assist by storing boxes of items in their main prayer hall.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B9%84%E0%B8%8A%E0%B8%A2%E0%B8%98%E0%B8%B2%E0%B8%A3%E0%B8%B2%E0%B8%A3%E0%B8%B2%E0%B8%A1","license":"CC BY-SA 4.0"}'::jsonb,
  'phuket',
  'Phuket',
  'ภูเก็ต',
  'South',
  'C',
  null,
  null,
