do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'e3345944-be79-521e-39cd-5024799fb1b9',
  'wat-chiang-man',
  'วัดเชียงมั่น',
  'Wat Chiang Man',
  'วัดเชียงมั่น (ไทยถิ่นเหนือ: ) เป็นวัดที่ตั้งอยู่ถนนราชภาคิไนย ตำบลศรีภูมิ อำเภอเมืองเชียงใหม่ จังหวัดเชียงใหม่ มีพระเสตังคมณี (พระแก้วขาว) และพระศิลาซึ่งเป็นพระพุทธรูปปางปราบช้างนาฬาคีรี ประดิษฐานอยู่ในพระวิหาร มีประวัติศาสตร์อันยาวนาน ปรากฏในตำนานพื้นเมืองเชียงใหม่และพงศาวดารโยนก หลังจากที่พญางำเมือง พ่อขุนรามคำแหงมหาราชและพญามังรายทรงสร้างเมืองเชียงใหม่ในปี พ.ศ. 1839 ทั้ง 3 พระองค์โปรดให้สร้างเจดีย์ และพญามังรายทรงประทับชั่วคราวในระหว่างควบคุมการสร้างเมือง ตรงหอนอนบ้านเชียงมั่น เรียกว่า "เวียงแก้ว" ทรงอุทิศตำหนักคุ้มหลวงเวียงเหล็ก ตั้งเป็นพระอารามหลวงแห่งแรกและพระราชทานนามว่า "วัดเชียงมั่น" จากนั้นคาดว่าเจดีย์พังลงมาในสมัยพระเจ้าติโลกราช (ครองราชย์ พ.ศ. 1985 - 2031) พระองค์จึงโปรดให้สร้างเจดีย์ใหม่ ทำด้วยศิลาแลง เมื่อปี พ.ศ. 2014 เมื่อเชียงใหม่ตกเป็นเมืองขึ้นของพม่า ในปี พ.ศ. 2094 วัดเชียงมั่นจึงถูกปล่อยร้าง จนปี พ.ศ. 2101 เจ้าฟ้ามังทรา (สมเด็จพระมหาธัมมิกะราชาธิราช) แห่งพม่า…',
  'Wat Chiang Man (Lanna: ᩅᩢ᩠ᨯᨩ᩠ᨿᨦᩉ᩠ᨾᩢ᩶ᩁ; Thai: วัดเชียงมั่น; sometimes also written as Wat Chiang Mun) is a Buddhist temple (Thai language: Wat) inside the old city (which is contained within the city walls and moat) of Chiang Mai, in northern Thailand.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B9%80%E0%B8%8A%E0%B8%B5%E0%B8%A2%E0%B8%87%E0%B8%A1%E0%B8%B1%E0%B9%88%E0%B8%99","license":"CC BY-SA 4.0"}'::jsonb,
