do $$
begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'5e8ad230-daf4-5713-fced-1ac45d578572',
  'wat-pah-nanachat',
  'วัดป่านานาชาติ',
  'Wat Pah Nanachat',
  'วัดป่านานาชาติ (อังกฤษ: Wat Pah Nanachat) เป็นวัดที่พระโพธิญาณเถร (ชา สุภทฺโท) ก่อตั้งเมื่อ พ.ศ. 2518 อยู่ห่างจากตัวอำเภอวารินชำราบ จังหวัดอุบลราชธานี ประมาณ 15 กิโลเมตร เพื่อเป็นสถานที่ปฏิบัติธรรมสำหรับชาวต่างชาติ วัดป่านานาชาติเป็นวัดฝ่ายมหานิกาย มีข้อวัตรปฏิบัติเช่นเดียวกับวัดหนองป่าพง โดยยึดปฏิปทาพร้อมทั้งข้อวัตรปฏิบัติของพระโพธิญาณเถร (ชา สุภทฺโท) พระสงฆ์วัดป่านานาชาติจึงเน้นการศึกษาและปฏิบัติวิปัสสนากรรมฐานเป็นหลัก ทั้งในรูปแบบภาษาไทยและภาษาอังกฤษสำหรับชาวต่างชาติ ในปี พ.ศ. 2518 วัดหนองป่าพงมีพระสงฆ์จำพรรษาอยู่มาก ส่งผลให้พระสงฆ์หาฟืนบ่มบาตรยาก พระโพธิญาณเถร (ชา สุภทฺโท)จึงอนุญาตให้พระชาวต่างชาติบางรูป ออกมาหาฟืนที่บ้านบุ่งหวาย แต่เดิมมีวัดร้างนามว่า"วัดหนองปลาเข็ง" อายุ 700 - 1,000 ปี ชาวบ้านบุ่งหวายมีจิตศรัทธาในพระสงฆ์วัดหนองป่าพง จึงได้นิมนต์คณะพระภิกษุสามเณรชุดแรกซึ่งมี 6 รูป บ่มบาตรและปักกลดปฏิบัติธรรมที่บ้านบุ่งหวาย เมื่ออยู่ได้ 3…',
  'Wat Pah Nanachat (Thai: วัดป่านานาชาติ, lit. ''International Forest Monastery'') is a Theravāda Buddhist monastery in northeast Thailand, about 15 kilometres from the city of Ubon Rachathani. It was established in 1975 by Ajahn Chah as a training community for non-Thais according to the norms of the Thai Forest Tradition. Resident monks, novices and postulants include a wide range of nationalities. The primary language of communication and instruction is English.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B8%9B%E0%B9%88%E0%B8%B2%E0%B8%99%E0%B8%B2%E0%B8%99%E0%B8%B2%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4","license":"CC BY-SA 4.0"}'::jsonb,
  'ubon-ratchathani',
  'Ubon Ratchathani',
  'อุบลราชธานี',
  'Northeast',
  'C',
  null,
  null,
