begin
insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'74eefe62-9b0d-5bd4-46c3-42b870006c7e',
  'wat-pha-lat',
  'วัดผาลาด',
  'Wat Pha Lat',
  'วัดผาลาด เป็นวัดราษฎร์สังกัดคณะสงฆ์ฝ่ายมหานิกาย ตั้งอยู่ในตำบลสุเทพ อำเภอเมืองเชียงใหม่ จังหวัดเชียงใหม่ ชื่อของวัดผาลาด มาจากคำว่า ผะเลิด เพราะคนที่เดินตามช้างมาตามลำธารน้ำตก แล้วเกิดลื่นหกล้มกันหลายคน บ้างก็ว่าช้างก็ลื่นเหมือนกัน เมื่อตั้งวัดจึงตั้งชื่อตามน้ำตก ชื่อของวัดปรากฏหลักฐานในเอกสารตำนานและพงศาวดาร มีประวัติศาสตร์ร่วมกับพระธาตุดอยสุเทพ มีการบันทึกไว้ว่าในสมัยพระเจ้ากือนา พระองค์ได้นำพระบรมสารีริกธาตุที่พระมหาสุมนเถระนำมาจากสุโขทัยอัญเชิญประทับบนหลังช้างเพื่อนำไปประดิษฐาน ณ ดอยสุเทพ ในครั้งพระองค์ทรงแวะพักที่บริเวณผาลาด เดิมเป็นวัดร้างกระทรวงศึกษาธิการประกาศยกเลิกเป็นวัดมีพระสงฆ์ เมื่อ 2 มีนาคม พ.ศ. 2524 ได้รับการบูรณะปฏิสังขรณ์ ฟื้นฟูขึ้นมาใหม่ ให้มีสถานภาพเป็นวัดและสถานที่ปฏิบัติธรรม อาคารเสนาสนะที่สำคัญ ได้แก่ เจดีย์เป็นศิลปะพม่าสมัยครูบาศรีวิชัย วิหารสร้างขึ้นในสมัยครูบาศรีวิชัยโดยช่างชาวพม่า ฐานโบราณสถาน (โบสถ์) (วิหารพระเจ้ากือนา) อยู่ทางด้านทิศตะวันออกเฉียงใต้ของเจดีย์…',
  'Wat Pha Lat (Lanna: ᩅᩢ᩠ᨯᨹᩣᩃᩣ᩠ᨯ; Thai: วัดผาลาด; lit. ''the monastery at the sloping rock''), also known as Wat Sakadagami (Lanna: ᩅᩢ᩠ᨯᩈᨠᨴᩣᨣᩣᨾᩦ; Thai: วัดสกทาคามี), is a Buddhist temple located on the slopes of Doi Suthep, above Chiang Mai. Founded by King Kuena of Lanna in the 14th century, Wat Pha Lat served originally as a resting place for pilgrims making the journey up to the Wat Phra That Doi Suthep.',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B8%9C%E0%B8%B2%E0%B8%A5%E0%B8%B2%E0%B8%94_(%E0%B8%88%E0%B8%B1%E0%B8%87%E0%B8%AB%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B9%80%E0%B8%8A%E0%B8%B5%E0%B8%A2%E0%B8%87%E0%B9%83%E0%B8%AB%E0%B8%A1%E0%B9%88)","license":"CC BY-SA 4.0"}'::jsonb,
