insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'05d52fc0-2c0d-58bb-5871-a0de92cccd98',
  'wat-phra-dhammakaya',
  'วัดพระธรรมกาย',
  'Wat Phra Dhammakaya',
  'วัดพระธรรมกาย เป็นวัดในสังกัดมหานิกาย ก่อตั้งเมื่อ 20 กุมภาพันธ์ พ.ศ. 2513 ตั้งอยู่ ณ ตำบลคลองสาม อำเภอคลองหลวง จังหวัดปทุมธานี วัดพระธรรมกายเป็นที่เคลือบแคลงสงสัยของประชาชน และเป็นที่วิพากษ์วิจารณ์ในสื่อมวลชนอย่างต่อเนื่อง แต่สื่อมวลชนจำนวนหนึ่งได้ขอขมาในภายหลัง อย่างไรก็ดี สภารักษาความสงบเรียบร้อยแห่งชาติได้ขึ้นวัดพระธรรมกายไว้ในบัญชีดำฐานเข้าข่ายเป็นภัยต่อความมั่นคงแห่งชาติ วันที่ 16 กุมภาพันธ์ พ.ศ. 2560 คณะรักษาความสงบแห่งชาติให้วัดพระธรรมกายเป็นเขตพื้นที่ควบคุมพิเศษ เพื่อจับกุมพระธัมมชโย',
  'Wat Phra Dhammakaya (Thai: วัดพระธรรมกาย, RTGS: Wat Phra Thammakai, pronounced [wát pʰráʔ tʰām.mā.kāːj]) is a Buddhist temple (wat) in Khlong Luang district, in the Pathum Thani province north of Bangkok, Thailand. It was founded in 1970 by the maechi (nun) Chandra Khonnokyoong and Luang Por Dhammajayo. It is the best-known and the fastest growing temple of the Dhammakaya tradition. This tradition, teaching Dhammakaya meditation (Vijja Dhammakaya), was started by the meditation master Luang Pu Sodh Candasaro in the early 20th century. Wat Phra Dhammakaya is one of the temples that emerged from this tradition and is part of the Mahā Nikāya fraternity. The temple is legally represented by the Dhammakaya Foundation. It aims to adapt traditional Buddhist values in modern society, doing so through modern technology and marketing methods. The temple has faced controversy and a government…',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B8%9E%E0%B8%A3%E0%B8%B0%E0%B8%98%E0%B8%A3%E0%B8%A3%E0%B8%A1%E0%B8%81%E0%B8%B2%E0%B8%A2","license":"CC BY-SA 4.0"}'::jsonb,
