insert into public.locations (
  id, slug, name_th, name_en, description_th, description_en, description_source,
  province_id, province, province_th, region, zone, district, address,
  latitude, longitude, coordinate_source, location_type, architectural_style,
  access_status, filming_permission_status, estimated_cost, contact_info, website_url, maps_url,
  verified_at, status, permission, filming, creative, tags, qid, commons_category, needs_admin_review
) values (
'370e95a8-cfc0-5abb-c350-7d5679b07460',
  'wat-rai-khing',
  'วัดไร่ขิง',
  'Wat Rai Khing',
  'วัดไร่ขิง เป็นวัดสำคัญตั้งอยู่ที่ริมแม่น้ำท่าจีน (เรียกอีกชื่อว่าแม่น้ำนครชัยศรี) ตำบลไร่ขิง อำเภอสามพราน จังหวัดนครปฐม สังกัดคณะสงฆ์ฝ่ายมหานิกาย สร้างโดย "สมเด็จพระพุฒาจารย์ (พุก)" มีหลวงพ่อวัดไร่ขิงซึ่งเป็นพระพุทธรูปปางมารวิชัยเป็นพระประธาน ที่ชาวนครปฐมเคารพนับถือ เดิมเป็นวัดราษฏร์ ต่อมาจึงยกฐานะขึ้นเป็นพระอารามหลวงชั้นตรี ชนิดสามัญ เมื่อวันที่ 10 กรกฎาคม พ.ศ. 2533',
  'Wat Rai Khing (Thai: วัดไร่ขิง, pronounced [wát râj kʰǐŋ]; lit. ''temple on ginger farm'') is another prominent and notable temple in Nakhon Pathom province in addition to Wat Phra Pathom Chedi, which is the provincial temple. Wat Rai Khing is located along the Tha Chin River (known locally as Nakhon Chai Si River), Tambon Rai Khing, Sam Phran district on Petchkasem Road, west of Bangkok. And not far from other attractions such as Sampran Riverside (Rose Garden), Samphran Elephant Ground & Zoo etc. It is a civilian monastery built in 1791 (reign of King Rama IV). Somdej Phra Phuttha Chan (Pook), who was a Sam Phran people named this temple after the tambon (subdistrict). When construction was completed, the Buddha image was brought from Wat Sala Poon and enshrined here, later the locals named the image Luang Por Wat Rai Khing (หลวงพ่อวัดไร่ขิง). The Buddha image is in the attitude of…',
  '{"type":"wikipedia","lang":"th","url":"https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B9%84%E0%B8%A3%E0%B9%88%E0%B8%82%E0%B8%B4%E0%B8%87","license":"CC BY-SA 4.0"}'::jsonb,
  'nakhon-pathom',
  'Nakhon Pathom',
  'นครปฐม',
  'Central',
  'B',
  'Sam Phran',
  null,
  13.7425,
  100.25861111111,
  '{"name":"Wikidata","url":"https://www.wikidata.org/wiki/Q13020942","property":"P625","confidence":100}'::jsonb,
